KN = '〇一二三四五六七八九'
def kan(n):
    if n < 10: return KN[n]
    return ('十' if n // 10 == 1 else KN[n // 10] + '十') + (KN[n % 10] if n % 10 else '')
def ages(n, rg):   # 一割が十八・十九、五割が二十〜二十四、二割五分が二十五〜二十九、一割が三十〜三十五、残り数人が四十代
    a = [rg.randint(18, 19) for _ in range(round(n * 0.10))] + [rg.randint(20, 24) for _ in range(round(n * 0.50))] + [rg.randint(25, 29) for _ in range(round(n * 0.25))] + [rg.randint(30, 35) for _ in range(round(n * 0.10))]
    while len(a) < n: a.append(rg.randint(40, 47))
    rg.shuffle(a); return a[:n]
N = 66
def build():
    rg = random.Random(20261101); sn = SN[:]; gn = GN[:]; rg.shuffle(sn); rg.shuffle(gn); sk = SKILL[:]; rg.shuffle(sk); hm = HOME[:]; rg.shuffle(hm)
    out = []
    for i, age in enumerate(ages(N, rg)):
        home = hm[i % len(hm)]; how = rg.choice(HOW); A = kan(age) + '歳'
        if age <= 19: sch = home.split('の')[1] + 'の公立高校'; bg = f'{A}です。{home}の出身で、今年{sch}を出たばかりの新入りです。{how}'
        elif age >= 40: sch = rg.choice(UNI); job = rg.choice(JOB); bg = f'{A}です。{home}の出身です。{job}を二十年近く勤めて、{how}。今は宴会場のまとめ役です'
        else:
            t = rg.random()
            if t < 0.2: sch = rg.choice(SEN)
            elif t < 0.3: sch = rg.choice(HS)
            else: sch = rg.choice(UNI)
            job = rg.choice(JOB); base = 22 if '大学' in sch else 20 if sch in SEN else 18; yrs = min(9, age - base)
            if age < 22 and '大学' in sch: bg = f'{A}、{home}の出身です。{sch}の在学中に、{how}'
            else: bg = f'{A}、{home}の出身です。' + (f'{job}を{kan(yrs)}年していました。' if yrs >= 1 else f'学校を出てすぐ、{job}の見習いをしていました。') + how
        kk, kn = rg.choice(KIN); kname = rg.choice(kn)
        if age <= 19 and kk == '姪': kk, kname = '妹', rg.choice(KIN[0][1])
        rel = rg.choice(REL) + f'{kk}の{kname}' + rg.choice(KWHERE)
        out.append({'nm': f'{sn[i]} {gn[i]}', 'age': age, 'home': home.replace('の', '・', 1), 'kin': kk, 'bg': bg, 'sc': f'{sch}です', 'sk': '特技は、' + sk[i % len(sk)], 'rel': rel,
                    'v': (rg.randint(-12, 12) - (6 if age >= 30 else 0), rg.randint(-10, 12))})
    return out
async def one(t, p, r, pi):
    for a in range(5):
        try: await edge_tts.Communicate(t, V, rate=f'{r:+d}%', pitch=f'{pi:+d}Hz').save(p); return
        except Exception: await asyncio.sleep(2 * (a + 1))
    raise RuntimeError('tts failed: ' + p)
async def main():
    os.makedirs(D, exist_ok=True); sem = asyncio.Semaphore(3); jobs = []; L = build(); M = []
    for i, m in enumerate(L):
        o = {'nm': m['nm'], 'age': m['age'], 'home': m['home'], 'kin': m['kin']}
        for f in ('bg', 'sc', 'sk', 'rel'):
            p = os.path.join(D, f'f{i}_{f}.mp3'); o[f] = {'text': m[f], 'file': f'cvbg/f{i}_{f}.mp3'}
            if not os.path.exists(p) or os.path.getsize(p) < 500:
                async def go(t=m[f], p=p, v=m['v']):
                    async with sem: await one(t.replace('…', '、'), p, v[1], v[0])
                jobs.append(go())
        M.append(o)
    await asyncio.gather(*jobs)
    open(os.path.join(ROOT, 'assets', 'voices', 'voices_cvbgf.js'), 'w').write('// 自動生成 (tools/add_cvbg_feast.py)。幕四 大広間の卓の侍女（固有の名前と身の上）\nwindow.VOICE_CVBG_F = ' + json.dumps(M, ensure_ascii=False) + ';\n')
    from collections import Counter
    print(len(jobs), len(M), len({m['nm'] for m in M}), sorted(Counter((m['age'] // 5) * 5 if m['age'] >= 20 else 18 for m in M).items()))
if __name__ == '__main__': asyncio.run(main())
